package com.oms.supplychain.service.wms;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import com.ruoyi.common.core.domain.R;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Real MySQL + HTTP warehouse simulator, including collection and crash recovery. */
class SharedReturnDispatchTest {
    RefundParcelsTest f;SharedReturnParcels parcels;SharedReturnDocuments documents;ExchangeReturnService exchanges;
    @BeforeEach void setup() throws Exception {
        f=new RefundParcelsTest();f.setup();f.server.removeContext("/");f.server.createContext("/",http->{String body=org.springframework.util.StreamUtils.copyToString(http.getRequestBody(),java.nio.charset.StandardCharsets.UTF_8);java.util.regex.Matcher match=java.util.regex.Pattern.compile("<(?:returnOrderCode|orderCode)>([^<]+)</").matcher(body);String sn=match.find()?match.group(1):"";if(http.getRequestURI().getQuery().contains("returnorder.create")){f.creates.incrementAndGet();f.lastCreate=body;}String response="<response><flag>success</flag><returnOrder><returnOrderCode>"+sn+"</returnOrderCode><returnOrderId>WH_SHARED</returnOrderId><warehouseCode>EXT-W</warehouseCode><ownerCode>EXT-O</ownerCode><status>ACCEPT</status></returnOrder></response>";byte[] bytes=response.getBytes(java.nio.charset.StandardCharsets.UTF_8);http.sendResponseHeaders(200,bytes.length);http.getResponseBody().write(bytes);http.close();});for(String t:Arrays.asList("wms_shared_return_receipt","wms_shared_return_document","wms_shared_return_member","wms_shared_return_parcel","wms_exchange_return"))f.f.f.jdbc.update("DELETE FROM "+t);
        Map<String,Object> connection=f.parcels.connections.usable("QM",1);connection.put("shared_return_waybill",1);
        exchanges=new ExchangeReturnService();ReflectionTestUtils.setField(exchanges,"db",f.f.f.db);ReflectionTestUtils.setField(exchanges,"routes",mock(WmsTenantRoutes.class));ReflectionTestUtils.setField(exchanges,"connections",f.parcels.connections);ReflectionTestUtils.setField(exchanges,"inventory",f.f.f.inventory);ReflectionTestUtils.setField(exchanges,"logs",f.parcels.logs);
        parcels=new SharedReturnParcels();parcels.db=f.f.f.db;parcels.routes=mock(WmsTenantRoutes.class);parcels.connections=f.parcels.connections;parcels.protocol=f.f.f.protocol;parcels.logs=f.parcels.logs;parcels.exchanges=exchanges;parcels.refunds=f.returns;
        parcels.authorization=mock(SharedReturnAuthorizationClient.class);when(parcels.authorization.context(anyString(),anyList(),anyString())).thenAnswer(a->{List<Map<String,Object>> rows=new ArrayList<>();for(Map<String,Object> m:(List<Map<String,Object>>)a.getArgument(1))rows.add(map("member_id",m.get("id"),"active",true,"dispatch",true,"allocate",true,"mixed",true));return R.ok(map("members",rows));});
        documents=new SharedReturnDocuments();documents.db=f.f.f.db;documents.parcels=parcels;documents.connections=f.parcels.connections;documents.protocol=f.f.f.protocol;documents.logs=f.parcels.logs;parcels.documents=documents;ReflectionTestUtils.setField(exchanges,"shared",parcels);ReflectionTestUtils.setField(f.returns,"common",parcels);
    }
    @AfterEach void stop(){f.stop();}
    Map<String,Object> input(long owner){Map<String,Object> input=f.input(owner,0);Map<String,Object> command=new LinkedHashMap<>((Map<String,Object>)input.get("request_json"));command.remove("refund_id");command.remove("refund_sn");command.put("exchange_sn","HH_TEST_"+owner);return map("source",command,"channel_id",1,"platform_tid","123456","platform_oid","123457","carrier","SF","waybill","SHARED-AUTOMATIC","owner_sn","HH_TEST_"+owner,"collect_seconds",120,"dispatch_enabled",1,"allocate_enabled",1,"mixed_enabled",1,"policy_revision",1);}
    Map<String,Object> advance(long owner){return parcels.advance("QM","EXCHANGE",owner,input(owner));}
    long parcel(){return id(f.f.f.db.one("SELECT id FROM wms_shared_return_parcel").get("id"));}
    @Test void duplicateInputDoesNotExtendCollectionWindowOrSendPrivateSource(){advance(1);Object due=f.f.f.db.one("SELECT dispatch_after FROM wms_shared_return_parcel").get("dispatch_after");advance(1);assertEquals(due,f.f.f.db.one("SELECT dispatch_after FROM wms_shared_return_parcel").get("dispatch_after"));assertEquals(0,f.creates.get());assertEquals(1L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_member",Long.class));assertEquals(0L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_document",Long.class));}
    @Test void lastActualNewMemberRestartsCollectionThenOnePhysicalThkIsSent(){advance(1);f.f.f.jdbc.update("UPDATE wms_shared_return_parcel SET dispatch_after=DATE_SUB(NOW(),INTERVAL 1 SECOND)");advance(2);assertEquals(0,f.creates.get());assertTrue(java.time.LocalDateTime.parse(text(f.f.f.db.one("SELECT dispatch_after FROM wms_shared_return_parcel").get("dispatch_after")).replace(' ','T')).isAfter(java.time.LocalDateTime.now().plusSeconds(110)));f.f.f.jdbc.update("UPDATE wms_shared_return_parcel SET dispatch_after=NOW()");advance(1);advance(2);assertEquals(1,f.creates.get());assertTrue(f.lastCreate.contains("<orderType>THRK</orderType>"));assertEquals(1L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_document",Long.class));assertEquals(2L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_tickets_goods WHERE sn=(SELECT return_sn FROM wms_shared_return_document)",Long.class));}
    @Test void frozenThkCannotSilentlyAppendOrLeaveAnOrphanPrivateSource(){advance(1);f.f.f.jdbc.update("UPDATE wms_shared_return_parcel SET dispatch_after=NOW()");advance(1);assertThrows(IllegalArgumentException.class,()->advance(2));assertEquals(1L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_member",Long.class));assertEquals(1L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_exchange_return",Long.class));assertEquals(1,f.creates.get());}
    @Test void pendingFrozenCommandRecoversWithoutAnotherDocument(){advance(1);f.f.f.jdbc.update("UPDATE wms_shared_return_parcel SET dispatch_after=NOW()");advance(1);f.f.f.jdbc.update("UPDATE wms_shared_return_document SET dispatch_state='PENDING',external_order='',attempts=0");documents.advance("QM",parcel());assertEquals(2,f.creates.get());assertEquals(1L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_document",Long.class));assertEquals("ACCEPTED",f.f.f.db.one("SELECT dispatch_state FROM wms_shared_return_document").get("dispatch_state"));}
    @Test void uncertainOriginalCommandOnlyQueriesAndNeverSubmitsAnotherCreate(){advance(1);f.f.f.jdbc.update("UPDATE wms_shared_return_parcel SET dispatch_after=NOW()");advance(1);f.f.f.jdbc.update("UPDATE wms_shared_return_document SET dispatch_state='UNKNOWN'");documents.advance("QM",parcel());assertEquals(1,f.creates.get());assertEquals("ACCEPTED",f.f.f.db.one("SELECT dispatch_state FROM wms_shared_return_document").get("dispatch_state"));}
    @Test void warehouseConflictCannotProduceASecondParcelForSameWaybill(){advance(1);f.f.f.jdbc.update("UPDATE wms_simulation_store_info SET external_warehouse='OTHER-W'");assertThrows(IllegalArgumentException.class,()->advance(2));assertEquals(1L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_parcel",Long.class));assertEquals(1L,f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_exchange_return",Long.class));assertEquals(0,f.creates.get());}
}
